<?php
declare(strict_types=1);requireRole('social-service-officer');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';$activePage='pending-handover';$db=database();$user=(int)$_SESSION['user_id'];$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);
if($_SERVER['REQUEST_METHOD']==='POST'){$id=filter_input(INPUT_POST,'lens_unit_id',FILTER_VALIDATE_INT);if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$id)$errors[]='Invalid lens handover.';if(!$errors)try{$db->beginTransaction();$q=$db->prepare("SELECT lu.*,ar.beneficiary_id,ar.item_id FROM contact_lens_units lu JOIN aid_requests ar ON ar.id=lu.aid_request_id WHERE lu.id=:id AND lu.sso_id=:user AND lu.status='pending-handover' FOR UPDATE");$q->execute(['id'=>$id,'user'=>$user]);$lens=$q->fetch();if(!$lens)throw new RuntimeException('This lens handover is no longer pending.');$db->prepare("INSERT INTO distributions(aid_request_id,beneficiary_id,item_id,quantity,distribution_type,source,distributed_by) VALUES(:aid,:beneficiary,:item,1,'request-based','officer-pool',:user)")->execute(['aid'=>$lens['aid_request_id'],'beneficiary'=>$lens['beneficiary_id'],'item'=>$lens['item_id'],'user'=>$user]);$db->prepare("UPDATE contact_lens_units SET status='distributed',distributed_by=:user,distributed_at=NOW() WHERE id=:id")->execute(['user'=>$user,'id'=>$id]);$db->prepare("INSERT INTO contact_lens_unit_history(lens_unit_id,event_type,aid_request_id,power,notes,performed_by) VALUES(:unit,'distributed',:aid,:power,'SSO verified NIC, address, power and unit ID',:user)")->execute(['unit'=>$id,'aid'=>$lens['aid_request_id'],'power'=>$lens['power'],'user'=>$user]);$db->prepare("UPDATE aid_requests SET status='distributed' WHERE id=:id")->execute(['id'=>$lens['aid_request_id']]);$db->commit();logActivity('SSO Handover','Distributed individual contact lens',$lens['unit_code'],'distributed');$_SESSION['flash_success']='Lens verified and final distribution recorded.';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=pending-lens-handover');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to complete handover.';}}
try{$q=$db->prepare("SELECT lu.id,lu.unit_code,lu.power,lu.status,lu.distributed_at,bo.order_code,b.full_name,b.nic,b.address,so.full_name subject_name FROM contact_lens_units lu JOIN contact_lens_bulk_orders bo ON bo.id=lu.bulk_order_id JOIN aid_requests ar ON ar.id=lu.aid_request_id JOIN beneficiaries b ON b.id=ar.beneficiary_id JOIN users so ON so.id=lu.assigned_by WHERE lu.sso_id=:user AND lu.status IN ('pending-handover','distributed') ORDER BY FIELD(lu.status,'pending-handover','distributed'),lu.id DESC");$q->execute(['user'=>$user]);$rows=$q->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$rows=[];$errors[]='Contact lens handovers are unavailable. Run migrations first.';}$counts=array_count_values(array_column($rows,'status'));
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pending Contact Lens Handover</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/social-service-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><h1>Pending Contact Lens Handover</h1></header><main class="dashboard-content"><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success)?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors))?></div><?php endif;?><section class="handover-summary-grid"><article class="handover-summary-card pending"><p>Pending Lenses</p><strong><?=(int)($counts['pending-handover']??0)?></strong><small>Verify identity and exact power</small></article><article class="handover-summary-card distributed"><p>Distributed</p><strong><?=(int)($counts['distributed']??0)?></strong></article></section><section class="handover-list-card"><div class="handover-list-header"><h2>Individual Lens Units</h2></div><div class="handover-table-wrap"><table class="handover-table"><thead><tr><th>Lens Unit ID</th><th>Bulk Order</th><th>Exact Power</th><th>Beneficiary</th><th>NIC</th><th>Address</th><th>Subject Officer</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9">No contact lens handovers assigned to you.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['unit_code'])?></td><td><?=htmlspecialchars($r['order_code'])?></td><td><?=sprintf('%+.2f',(float)$r['power'])?></td><td><?=htmlspecialchars($r['full_name'])?></td><td><?=htmlspecialchars($r['nic'])?></td><td><?=htmlspecialchars($r['address'])?></td><td><?=htmlspecialchars($r['subject_name'])?></td><td><?=ucwords(str_replace('-',' ',$r['status']))?></td><td><?php if($r['status']==='pending-handover'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken())?>"><input type="hidden" name="lens_unit_id" value="<?=(int)$r['id']?>"><button class="approve-button">Verify &amp; Distribute</button></form><?php else:?><?=htmlspecialchars($r['distributed_at']?:'â€”')?><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
